"use client";

// /blog ve /blog/[slug] segment'lerinin hata sınırı. apiv3 anlık takılır da server
// render çökerse (örn. getBlogPosts "Failed to fetch data"), tüm site kabuğunu
// global-error'a düşürmek yerine root layout (header/footer) korunur ve içerik
// alanında "tekrar dene" gösterilir. Hata yine Sentry'e raporlanır.
import * as Sentry from "@sentry/nextjs";
import { useEffect } from "react";

export default function BlogError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    Sentry.captureException(error);
  }, [error]);

  return (
    <main>
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-12 tw-font-display">
        <div className="tw-flex tw-justify-center">
          <div className="tw-max-w-[560px] tw-text-center tw-py-12">
            <h2 className="tw-text-[24px] tw-font-bold tw-text-[#14101c] tw-mt-2 tw-mb-3">
              Couldn&apos;t load the blog
            </h2>
            <p className="tw-text-[#5d556c] tw-mb-6">
              Something went wrong while loading this page. Please try again in a
              moment.
            </p>
            <button
              onClick={() => reset()}
              className="tw-inline-flex tw-items-center tw-gap-1 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-px-5 tw-py-3 tw-no-underline tw-transition-colors tw-border-0 tw-cursor-pointer"
            >
              Try again
            </button>
          </div>
        </div>
      </div>
    </main>
  );
}
